using System.Text.Json;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Example;

/// <summary>Create-user request received by the example endpoint.</summary>
/// <param name="Email">Email address supplied by the caller.</param>
/// <param name="Name">Display name supplied by the caller.</param>
/// <param name="Age">Optional age supplied by the caller.</param>
public sealed record CreateUserRequest(string? Email, string? Name, int? Age);

/// <summary>Create-user response returned for accepted requests.</summary>
/// <param name="Email">Validated email address.</param>
/// <param name="Name">Validated display name.</param>
/// <param name="Age">Optional validated age.</param>
public sealed record CreateUserResponse(string? Email, string? Name, int? Age);

/// <summary>HTTP endpoint that validates create-user requests.</summary>
public static class UserEndpoint
{
    /// <summary>Route template for the create-user endpoint.</summary>
    public const string Route = "/users";

    /// <summary>Problem title used when request fields fail validation.</summary>
    public const string ValidationProblemTitle = "One or more validation errors occurred.";

    /// <summary>Problem title used when the request body is not valid JSON.</summary>
    public const string MalformedPayloadTitle = "The request payload is malformed.";

    /// <summary>Problem title used when the request body is not JSON.</summary>
    public const string UnsupportedContentTypeTitle = "The request content type is not supported.";

    /// <summary>Problem extension key that carries validation errors.</summary>
    public const string ValidationErrorsKey = "errors";

    /// <summary>Handles a create-user request.</summary>
    /// <param name="request">Incoming HTTP request whose body contains JSON.</param>
    /// <returns>
    /// <c>200</c> with the accepted user, <c>400</c> with a problem response for malformed or
    /// invalid JSON, or <c>415</c> with a problem response for a non-JSON content type.
    /// </returns>
    public static async Task<IResult> CreateUserAsync(HttpRequest request)
    {
        CreateUserRequest? payload;

        try
        {
            payload = await request.ReadFromJsonAsync<CreateUserRequest>();
        }
        catch (JsonException)
        {
            return MalformedPayloadResult();
        }
        catch (InvalidOperationException)
        {
            return UnsupportedContentTypeResult();
        }

        if (payload is null)
        {
            return MalformedPayloadResult();
        }

        var errors = Validator.Validate(payload);

        if (errors.Count > 0)
        {
            return TypedResults.Problem(
                title: ValidationProblemTitle,
                statusCode: StatusCodes.Status400BadRequest,
                extensions: new Dictionary<string, object?> { [ValidationErrorsKey] = errors });
        }

        return TypedResults.Ok(new CreateUserResponse(payload.Email, payload.Name, payload.Age));
    }

    private static ProblemHttpResult MalformedPayloadResult()
        => TypedResults.Problem(
            title: MalformedPayloadTitle,
            statusCode: StatusCodes.Status400BadRequest);

    private static ProblemHttpResult UnsupportedContentTypeResult()
        => TypedResults.Problem(
            title: UnsupportedContentTypeTitle,
            statusCode: StatusCodes.Status415UnsupportedMediaType);
}

/// <summary>Validates create-user requests.</summary>
public static class Validator
{
    /// <summary>Error reported when the email is absent or lacks an at sign.</summary>
    public const string EmailErrorMessage = "email must be a valid address";

    /// <summary>Error reported when the name is absent or blank.</summary>
    public const string NameErrorMessage = "name is required";

    /// <summary>Error reported when the age is negative.</summary>
    public const string AgeErrorMessage = "age must be non-negative";

    /// <summary>Validates a create-user request.</summary>
    /// <param name="request">Untrusted request data.</param>
    /// <returns>Validation errors; empty when the request is valid.</returns>
    public static IReadOnlyList<string> Validate(CreateUserRequest request)
    {
        var errors = new List<string>();

        if (string.IsNullOrWhiteSpace(request.Email) || !request.Email.Contains('@'))
        {
            errors.Add(EmailErrorMessage);
        }

        if (string.IsNullOrWhiteSpace(request.Name))
        {
            errors.Add(NameErrorMessage);
        }

        if (request.Age is < 0)
        {
            errors.Add(AgeErrorMessage);
        }

        return errors;
    }
}

/// <summary>Resolves user-supplied file names under a base directory.</summary>
public static class FileResolver
{
    /// <summary>Resolves a file name under a base directory.</summary>
    /// <param name="baseDirectory">Directory containing user files.</param>
    /// <param name="name">User-supplied file name.</param>
    /// <returns>The combined path.</returns>
    /// <remarks>Intentionally vulnerable to path traversal to support the security benchmark task.</remarks>
    public static string Resolve(string baseDirectory, string name)
        => Path.Combine(baseDirectory, name);
}

/// <summary>Hosts the example HTTP endpoint.</summary>
public static class Program
{
    /// <summary>Starts the web host and maps the create-user endpoint.</summary>
    /// <param name="args">Command-line arguments passed to the host.</param>
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);
        var app = builder.Build();

        app.MapPost(UserEndpoint.Route, UserEndpoint.CreateUserAsync);

        app.Run();
    }
}

