using System.Text;
using Example;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.HttpResults;
using Xunit;

namespace Example.Tests;

/// <summary>Tests for <see cref="Validator"/>, <see cref="UserEndpoint"/>, and <see cref="FileResolver"/>.</summary>
public class ValidationTests
{
    /// <summary>Verifies that a valid request produces no errors.</summary>
    [Fact]
    public void AcceptsValidRequest()
    {
        var errors = Validator.Validate(new CreateUserRequest("a@b.co", "Ada", 30));
        Assert.Empty(errors);
    }

    /// <summary>Verifies that a missing email is rejected.</summary>
    [Fact]
    public void RejectsMissingEmail()
    {
        var errors = Validator.Validate(new CreateUserRequest(null, "Ada", 30));
        Assert.Contains(errors, error => error.Contains("email"));
    }

    /// <summary>Verifies that a negative age is rejected.</summary>
    [Fact]
    public void RejectsNegativeAge()
    {
        var errors = Validator.Validate(new CreateUserRequest("a@b.co", "Ada", -1));
        Assert.Contains(errors, error => error.Contains("age"));
    }

    /// <summary>Verifies that a normal file name resolves under the base directory.</summary>
    [Fact]
    public void ResolvesNormalFileName()
    {
        var result = FileResolver.Resolve("/srv/user-files", "avatar.png");
        Assert.EndsWith("/srv/user-files/avatar.png", result.Replace('\\', '/'));
    }

    /// <summary>Verifies that the endpoint returns the user for a valid payload.</summary>
    [Fact]
    public async Task EndpointAcceptsValidPayload()
    {
        var request = JsonRequest("""{"email":"a@b.co","name":"Ada","age":30}""");

        var result = await UserEndpoint.CreateUserAsync(request);

        var ok = Assert.IsType<Ok<CreateUserResponse>>(result);
        Assert.Equal(StatusCodes.Status200OK, ok.StatusCode);
        Assert.Equal("a@b.co", ok.Value?.Email);
        Assert.Equal("Ada", ok.Value?.Name);
        Assert.Equal(30, ok.Value?.Age);
    }

    /// <summary>Verifies that the endpoint returns a problem response when required fields are missing.</summary>
    [Fact]
    public async Task EndpointRejectsMissingFields()
    {
        var request = JsonRequest("""{"age":30}""");

        var result = await UserEndpoint.CreateUserAsync(request);

        var problem = Assert.IsType<ProblemHttpResult>(result);
        Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
        Assert.Equal("application/problem+json", problem.ContentType);
        Assert.Equal(UserEndpoint.ValidationProblemTitle, problem.ProblemDetails.Title);

        var errors = Assert.IsAssignableFrom<IReadOnlyList<string>>(
            problem.ProblemDetails.Extensions[UserEndpoint.ValidationErrorsKey]);
        Assert.Contains(Validator.EmailErrorMessage, errors);
        Assert.Contains(Validator.NameErrorMessage, errors);
    }

    /// <summary>Verifies that the endpoint returns a problem response for malformed JSON.</summary>
    [Fact]
    public async Task EndpointRejectsMalformedPayload()
    {
        var request = JsonRequest("""{"email":"a@b.co","name":""");

        var result = await UserEndpoint.CreateUserAsync(request);

        var problem = Assert.IsType<ProblemHttpResult>(result);
        Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
        Assert.Equal("application/problem+json", problem.ContentType);
        Assert.Equal(UserEndpoint.MalformedPayloadTitle, problem.ProblemDetails.Title);
    }

    /// <summary>Verifies that the endpoint returns a problem response for an empty payload.</summary>
    [Fact]
    public async Task EndpointRejectsEmptyPayload()
    {
        var request = JsonRequest(string.Empty);

        var result = await UserEndpoint.CreateUserAsync(request);

        var problem = Assert.IsType<ProblemHttpResult>(result);
        Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
        Assert.Equal(UserEndpoint.MalformedPayloadTitle, problem.ProblemDetails.Title);
    }

    private static HttpRequest JsonRequest(string body)
    {
        var context = new DefaultHttpContext();
        context.Request.Method = HttpMethods.Post;
        context.Request.ContentType = "application/json";
        context.Request.Body = new MemoryStream(Encoding.UTF8.GetBytes(body));
        return context.Request;
    }
}

